+            let hangTimer: ReturnType<typeof setTimeout> | undefined;
+            const armHang = () => {
+              if (hangTimer) clearTimeout(hangTimer);
+              hangTimer = setTimeout(() => { reason = "hang"; ac.abort(); }, HANG_MS);
+            };
+            const drop = () => {
+              if (hangTimer) clearTimeout(hangTimer);
+              clearTimeout(hardTimer);
+            };
+            let up: RawUpstream | undefined;
+            armHang();
             const hardTimer = setTimeout(() => { reason = "hard"; ac.abort(); }, UPSTREAM_TIMEOUT_MS);
