-            let seen = "";
-            let flushed = false;
             try {
+              up = await forward(req, raw, ac.signal);
+              if (up.status < 200 || up.status >= 300) {
+                drop();
+                console.log(`[shim] ${req.method} ${url.pathname} -> upstream ${up.status} (SSE error event)`);
+                up.stream.destroy();
+                fail(`shim: upstream ${up.status}`);
+                return true;
+              }
+              const reader = (Readable.toWeb(up.stream) as unknown as ReadableStream<Uint8Array>).getReader();
+              const buffered: Uint8Array[] = [];
+              const dec = new TextDecoder();
+              let seen = "";
+              let flushed = false;
               for (;;) {
-                let hang: ReturnType<typeof setTimeout> | undefined;
-                const readP = reader.read();
-                const hangP = new Promise<never>((_, rej) => {
-                  hang = setTimeout(() => { reason = "hang"; ac.abort(); rej(new Error("hang")); }, HANG_MS);
-                });
-                let step: ReadableStreamReadResult<Uint8Array>;
-                try {
-                  step = await Promise.race([readP, hangP]);
-                } finally {
-                  if (hang) clearTimeout(hang);
-                }
-                if (closed) { await reader.cancel().catch(() => {}); return true; }
+                const step = await reader.read();
+                if (closed) { await reader.cancel().catch(() => {}); drop(); return true; }
                 if (step.done) break;
+                armHang();
                 const chunk = step.value;
                 if (!flushed) {
                   buffered.push(chunk);
                   seen += dec.decode(chunk, { stream: true });
@@ -535,33 +533,30 @@
